var TEXT_LIST = ['解一元一次方程 2x+3=5x+7','原方程：2x+3=5x+7','1','移项','2x-5x=7-3','2','合并同类项','-3x=4','3','系数化为 1','x=-4/3'];
const visual = {
  prepare: function(input) {
    return TEXT_LIST.map(function(t){ return {kind:'text', payload:t}; });
  },
  render: function(input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 760;
    var H = (input && input.viewport && input.viewport.heightDu) || 560;
    function roundRect(x,y,w,h,r) {
      var c = [];
      c.push(['M', x+r, y]);
      c.push(['L', x+w-r, y]);
      c.push(['C', x+w-r+r*0.5523, y, x+w, y+r-r*0.5523, x+w, y+r]);
      c.push(['L', x+w, y+h-r]);
      c.push(['C', x+w, y+h-r+r*0.5523, x+w-r+r*0.5523, y+h, x+w-r, y+h]);
      c.push(['L', x+r, y+h]);
      c.push(['C', x+r-r*0.5523, y+h, x, y+h-r+r*0.5523, x, y+h-r]);
      c.push(['L', x, y+r]);
      c.push(['C', x, y+r-r*0.5523, x+r-r*0.5523, y, x+r, y]);
      c.push(['Z']);
      return c;
    }
    var margin = Math.max(18, Math.min(36, W * 0.05));
    var contentW = W - margin * 2;
    var topY = Math.max(18, H * 0.04);
    var titleSize = Math.max(18, Math.min(26, W * 0.032));
    var subSize = Math.max(14, Math.min(18, W * 0.022));
    var titleY = topY + titleSize;
    var origY = titleY + subSize + 14;
    var cardsTop = origY + 16;
    var bottomPad = Math.max(16, H * 0.03);
    var available = H - cardsTop - bottomPad;
    var gap = Math.max(14, Math.min(28, available * 0.05));
    var cardH = (available - gap * 2) / 3;
    cardH = Math.max(82, Math.min(150, cardH));
    var total = cardH * 3 + gap * 2;
    if (total > available) {
      gap = Math.max(8, (available - cardH * 3) / 2);
    }
    var cardW = contentW;
    var cardX = margin;
    var r = Math.max(10, Math.min(18, cardH * 0.12));
    var paths = [];
    var children = [];
    var cards = [];
    for (var i = 0; i < 3; i++) {
      var cy = cardsTop + i * (cardH + gap);
      cards.push({y: cy});
      paths.push({id: 'card' + i, commands: roundRect(cardX, cy, cardW, cardH, r)});
      children.push({type: 'path', pathId: 'card' + i, fill: '#f7f9fc', stroke: '#c9d3e0', strokeWidth: 1.2});
    }
    for (var j = 0; j < 2; j++) {
      var y1 = cards[j].y + cardH + 3;
      var y2 = cards[j + 1].y - 3;
      var ax = W / 2;
      paths.push({id: 'arrow' + j, commands: visualSdk.arrow(ax, y1, ax, y2, {headSize: 6})});
      children.push({type: 'path', pathId: 'arrow' + j, fill: 'none', stroke: '#5b7bb2', strokeWidth: 1.5});
    }
    var tagR = Math.max(12, Math.min(20, cardH * 0.15));
    var titleFont = Math.max(15, Math.min(20, cardH * 0.15));
    var eqFont = Math.max(16, Math.min(22, cardH * 0.17));
    var stepFont = Math.max(14, Math.min(18, tagR * 1.1));
    for (var k = 0; k < 3; k++) {
      var cardY = cards[k].y;
      var tagCx = cardX + tagR + 16;
      var tagCy = cardY + cardH / 2;
      paths.push({id: 'tag' + k, commands: visualSdk.circle(tagCx, tagCy, tagR)});
      children.push({type: 'path', pathId: 'tag' + k, fill: '#e8eef8', stroke: '#5b7bb2', strokeWidth: 1.2});
      var textX = cardX + tagR * 2 + 30;
      children.push({type: 'label', x: tagCx, y: tagCy + stepFont * 0.35, text: TEXT_LIST[2 + k * 3], fontSize: stepFont, fontWeight: '600', fill: '#2f4f7f', textAnchor: 'middle'});
      children.push({type: 'label', x: textX, y: cardY + cardH * 0.38, text: TEXT_LIST[3 + k * 3], fontSize: titleFont, fontWeight: '600', fill: '#1f2d3d', textAnchor: 'start'});
      children.push({type: 'label', x: textX, y: cardY + cardH * 0.72, text: TEXT_LIST[4 + k * 3], fontSize: eqFont, fill: '#0f2a4a', textAnchor: 'start', fontFamily: 'monospace'});
    }
    children.push({type: 'label', x: W / 2, y: titleY, text: TEXT_LIST[0], fontSize: titleSize, fontWeight: '600', fill: '#1f2d3d', textAnchor: 'middle'});
    children.push({type: 'label', x: W / 2, y: origY, text: TEXT_LIST[1], fontSize: subSize, fill: '#44556b', textAnchor: 'middle'});
    return {schemaVersion: 1, sceneId: 'flow-one-linear-equation', revision: input.revision, viewBox: {x: 0, y: 0, width: W, height: H}, paths: paths, root: {type: 'group', children: children}};
  }
};
